# AI Office v1.9 Part C Dashboard Certification Release Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v1.9-part-c-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @(
 "config\operations-integrations",
 "workspace\operations-integrations\certification",
 "dashboard\public",
 "dashboard\data",
 "scripts\operations-integrations",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\operations-integrations\release-manifest.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\operations-integrations\New-AIOfficeOperationsDashboardSnapshot.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\operations-integrations-module.js" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\operations-integrations-module.css" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\operations-integrations\Install-AIOfficeOperationsDashboardIntegration.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\operations-integrations\Test-AIOfficeOperationsDashboard.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\operations-integrations\Certify-AIOfficeOperationsIntegrations.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\operations-integrations\Publish-AIOfficeOperationsIntegrationsRelease.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\operations-integrations\Test-AIOfficeOperationsIntegrations.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v1.9-Release-Notes.md" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v1.9-Part-C-Dashboard-Certification-Release.md" -Base64Content ""
$Scripts = @(
 "E:\AI\AI-Office\scripts\operations-integrations\New-AIOfficeOperationsDashboardSnapshot.ps1",
 "E:\AI\AI-Office\scripts\operations-integrations\Install-AIOfficeOperationsDashboardIntegration.ps1",
 "E:\AI\AI-Office\scripts\operations-integrations\Test-AIOfficeOperationsDashboard.ps1",
 "E:\AI\AI-Office\scripts\operations-integrations\Certify-AIOfficeOperationsIntegrations.ps1",
 "E:\AI\AI-Office\scripts\operations-integrations\Publish-AIOfficeOperationsIntegrationsRelease.ps1",
 "E:\AI\AI-Office\scripts\operations-integrations\Test-AIOfficeOperationsIntegrations.ps1"
)
foreach ($ScriptPath in $Scripts) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $ScriptPath + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; ")) }
}
& "E:\AI\AI-Office\scripts\operations-integrations\New-AIOfficeOperationsDashboardSnapshot.ps1" | Out-Null
& "E:\AI\AI-Office\scripts\operations-integrations\Install-AIOfficeOperationsDashboardIntegration.ps1" | Out-Null
Write-Host ""
Write-Host "AI Office v1.9 Part C Dashboard, Certification, and Release installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan